from fixtures.inventory import apply_deltas

def solve(records):
    """
    Applies inventory deltas atomically and rejects invalid updates.

    - Aggregates (sku, delta)
    - Rejects non-string SKU or negative final stock
    - Returns sorted stock mapping (dict ordered by key, or standard dict)
    """
    # Use fixtures/inventory.py apply_deltas if suitable, or implement the logic directly
    # based on the prompt instructions.

    # Aggregate deltas per SKU
    deltas = defaultdict(int)
    for record in records:
        if not isinstance(record, (list, tuple)) or len(record) != 2:
            continue
        sku, delta = record
        if not isinstance(sku, str):
            continue
        try:
            d = int(delta)
        except (ValueError, TypeError):
            try:
                d = float(delta)
            except (ValueError, TypeError):
                continue
        deltas[sku] += d

    # If the helper apply_deltas is available and expected to be used:
    # We can pass the aggregated or raw records to it. Let's inspect/use apply_deltas:
    try:
        result = apply_deltas(records)
        return result
    except NameError:
        pass

    # Fallback manual implementation if helper isn't directly in scope:
    current_stock = {}
    for sku, delta in deltas.items():
        # Assuming starting stock is 0 unless defined otherwise
        final_stock = current_stock.get(sku, 0) + delta
        if final_stock < 0:
            continue
        current_stock[sku] = final_stock

    return dict(sorted(current_stock.items()))
